// MergeTimelineSystemEntry performs a merge with any union data inside the TimelineEntry, using the provided TimelineSystemEntry
func (t *TimelineEntry) MergeTimelineSystemEntry(v TimelineSystemEntry) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"kind":"system"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

func (t TimelineEntry) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"kind"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t TimelineEntry) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "alerts":
		return t.AsTimelineAlertsEntry()
	case "delivery":
		return t.AsTimelineDeliveryEntry()
	case "notes":
		return t.AsTimelineNoteEntry()
	case "status":
		return t.AsTimelineStatusEntry()
	case "system":
		return t.AsTimelineSystemEntry()
	case "timers":
		return t.AsTimelineTimersEntry()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t TimelineEntry) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *TimelineEntry) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

